create type public.app_role as enum ('reviewer');
create table public.user_roles (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,role public.app_role not null,unique(user_id,role));
grant select on public.user_roles to authenticated; grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create policy own_role_read on public.user_roles for select to authenticated using(user_id=auth.uid());
create function public.has_role(_user_id uuid,_role public.app_role) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
revoke all on function public.has_role(uuid,public.app_role) from public,anon; grant execute on function public.has_role(uuid,public.app_role) to authenticated,service_role;
create table public.correction_reports (id uuid primary key default gen_random_uuid(),rule_id text not null,rule_version text not null,message text not null check(length(message) between 10 and 2000),status text not null default 'open' check(status in ('open','resolved')),created_at timestamptz not null default now());
grant select,update on public.correction_reports to authenticated; grant all on public.correction_reports to service_role;
alter table public.correction_reports enable row level security;
create policy reviewer_read_reports on public.correction_reports for select to authenticated using(public.has_role(auth.uid(),'reviewer'));
create policy reviewer_update_reports on public.correction_reports for update to authenticated using(public.has_role(auth.uid(),'reviewer')) with check(public.has_role(auth.uid(),'reviewer'));
create table public.evidence_reviews (id uuid primary key default gen_random_uuid(),source_id text not null,rule_id text not null,quotation text not null check(length(quotation)>=20),section text not null,policy_edition text not null,reviewer_name text not null,review_due date not null,conflicts text not null default '',status text not null default 'draft' check(status in ('draft','approved')),created_by uuid not null,created_at timestamptz not null default now(),human_verified_at timestamptz);
grant select,insert,update on public.evidence_reviews to authenticated; grant all on public.evidence_reviews to service_role;
alter table public.evidence_reviews enable row level security;
create policy reviewers_read_evidence on public.evidence_reviews for select to authenticated using(public.has_role(auth.uid(),'reviewer'));
create policy reviewers_insert_evidence on public.evidence_reviews for insert to authenticated with check(public.has_role(auth.uid(),'reviewer') and created_by=auth.uid() and status='draft');
create policy reviewers_update_evidence on public.evidence_reviews for update to authenticated using(public.has_role(auth.uid(),'reviewer')) with check(public.has_role(auth.uid(),'reviewer'));
create table public.evidence_history(id uuid primary key default gen_random_uuid(),review_id uuid not null references public.evidence_reviews(id),actor_id uuid not null,changed_at timestamptz not null default now(),record jsonb not null);
grant select on public.evidence_history to authenticated;grant all on public.evidence_history to service_role;
alter table public.evidence_history enable row level security;
create policy reviewer_history on public.evidence_history for select to authenticated using(public.has_role(auth.uid(),'reviewer'));
create function public.audit_evidence_review() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.status='approved' and (TG_OP='INSERT' or old.status is distinct from new.status) then new.human_verified_at=now(); end if; if TG_OP='UPDATE' and old.status='approved' and new.status='approved' then raise exception 'Create a new draft revision rather than editing approved evidence';end if;insert into public.evidence_history(review_id,actor_id,record) values(new.id,auth.uid(),to_jsonb(new));return new;end $$;
create trigger audit_review before update on public.evidence_reviews for each row execute function public.audit_evidence_review();
create view public.approved_evidence with (security_barrier=true) as select id,source_id,rule_id,quotation,section,policy_edition,reviewer_name,review_due,conflicts,human_verified_at from public.evidence_reviews where status='approved';
grant select on public.approved_evidence to anon,authenticated;
create table public.source_observations(id uuid primary key default gen_random_uuid(),source_id text not null,observed_at timestamptz not null default now(),http_status integer,content_hash text,outcome text not null);
grant select on public.source_observations to authenticated; grant all on public.source_observations to service_role;
alter table public.source_observations enable row level security;
create policy reviewer_observations on public.source_observations for select to authenticated using(public.has_role(auth.uid(),'reviewer'));
create index correction_status_date on public.correction_reports(status,created_at desc);
create index observations_source_date on public.source_observations(source_id,observed_at desc);
create index reviews_source on public.evidence_reviews(source_id);
create index review_history_review on public.evidence_history(review_id);